import fs from 'node:fs';import path from 'node:path';import {fileURLToPath} from 'node:url';import yaml from 'js-yaml';
import {buildPatches,PRESETS,REPO_ROOT,patchFileFor} from './build-agent-preset-patches.mjs';
import {BUNDLED_MCP} from '../dsh-mcp-entry.mjs';
// Existing preset sources remain authoritative. This root bundle is generated
// for DSH's one-package installer; no profile edits or local junctions required.
export function buildDshBundle({check=false,root=REPO_ROOT}={}){
 const results=buildPatches({check,root});
 const owned=[...PRESETS.map(p=>patchFileFor(p,root)),path.join(root,'plugins/qq-agent-presets/presets/campus-summary.patch.yml'),path.join(root,'plugins/qq-agent-presets/session-titles.patch.yml')];
 const rewrite=value=>Array.isArray(value)?value.map(rewrite):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([k,v])=>[k,k==='name'&&typeof v==='string'&&v.startsWith('qq-agent-presets/')?'qq-bridge/plugins/'+v:rewrite(v)])):value;
 const rows=[{id:'qq-mode',name:'./plugins/qq-mode-console/lib/index.js',config:{}},{id:'qq-launcher',name:'qq-bridge',config:{}},...Object.keys(BUNDLED_MCP).map(serverName=>({id:'mcp-'+serverName,name:'qq-bridge/dsh-mcp-entry.mjs',config:{serverName}}))];
 const patches=[{insert:rows},...owned.flatMap(file=>rewrite(yaml.load(fs.readFileSync(file,'utf8'))))];
 const outputs={
  'cordis.patch.yml':'# Generated by scripts/build-dsh-bundle.mjs. Edit the preset sources instead.\n'+yaml.dump(patches,{lineWidth:-1,noRefs:true}),
  'dsh-client.js':'// Generated by scripts/build-dsh-bundle.mjs from the launcher client.\n'+fs.readFileSync(path.join(root,'plugins/qq-launcher/lib/client.js'),'utf8').replace("id: 'qq-launcher'","id: 'qq-bridge'")
 };
 for(const [relative,content]of Object.entries(outputs)){const file=path.join(root,relative),changed=!fs.existsSync(file)||fs.readFileSync(file,'utf8')!==content;if(changed&&!check)fs.writeFileSync(file,content);results.push({file,changed});}
 return results;
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const check=process.argv.includes('--check'),out=buildDshBundle({check});console.log(JSON.stringify({files:out.length,stale:out.filter(r=>r.changed).map(r=>path.relative(REPO_ROOT,r.file)),check}));if(check&&out.some(r=>r.changed))process.exitCode=1;}
